styles:
.page-post .post-quote { margin: clamp(6px, 2vw, 18px) 0 clamp(30px, 4vw, 48px); padding: clamp(20px, 2.6vw, 30px) clamp(24px, 3vw, 36px); border-left: 3px solid var(--red); background: var(--bg-alt); border-radius: 0 var(--radius) var(--radius) 0;}
.page-post .post-quote p { font-family: var(--post-serif); font-weight: 400; font-size: clamp(19px, 1.7vw, 24px); line-height: 1.5; color: var(--grey-900); margin-bottom: .6em; font-style: italic;}
.page-post .post-quote cite { display: block; font-family: var(--font-body); font-style: normal; font-size: 15px; color: var(--grey-500);}
.page-post .post-quote cite strong { color: var(--grey-900); font-weight: 400;}
